  [2339] = {id=2339,name="Find the Gems and Power Source",questSort=1517,canonicalZone=1517,zoneName="Zone 1517",requiredLevel=37,questLevel=44,requiredRaces=690,requiredClasses=0,prerequisitesAll={},prerequisitesAny={2338},children={},objectiveText={"Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman.","","From the journal, you know...","* The ruby has been stashed in a barricaded Shadowforge area.","* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.","* The sapphire has been claimed by Grimlok, the trogg leader."},objectiveGroups={nil,nil,{{7669},{7670},{7671},{7672}}},sourceItem=7668,requiredItems={},extraObjectives={},starters={{kind="npc",id=6868,name="Jarkal Mossmeld",dataSource="Database/TBC/tbcNpcDB.lua",points={{areaId=3,mapName="Badlands",x=2.42,y=46.06}}}},finishers={{kind="npc",id=6868,name="Jarkal Mossmeld",dataSource="Database/TBC/tbcNpcDB.lua",points={{areaId=3,mapName="Badlands",x=2.42,y=46.06}}}},objectives={{kind="item",id=7669,name="Shattered Necklace Ruby",dataSource="Database/TBC/tbcItemDB.lua",points={}},{kind="item",id=7670,name="Shattered Necklace Sapphire",dataSource="Database/TBC/tbcItemDB.lua",points={}},{kind="item",id=7671,name="Shattered Necklace Topaz",dataSource="Database/TBC/tbcItemDB.lua",points={}},{kind="item",id=7672,name="Shattered Necklace Power Source",dataSource="Database/TBC/tbcItemDB.lua",points={}}},exclusiveTo={},category="dungeon",geographic=false,kinds={"dungeon","group_content","item_mechanic","one_time"},recurrence="permanent",permanent=true,eventOnly=false,phaseStatus="current",sourceStatus="runtime",starter={kind="npc",id=6868,name="Jarkal Mossmeld",point={areaId=3,mapName="Badlands",x=2.42,y=46.06}},finisher={kind="npc",id=6868,name="Jarkal Mossmeld",point={areaId=3,mapName="Badlands",x=2.42,y=46.06}},objective=