  [6607] = {id=6607,name="Nat Pagle, Angler Extreme",questSort=-101,canonicalZone=15,zoneName="Dustwallow Marsh",requiredLevel=35,questLevel=45,requiredRaces=0,requiredClasses=0,requiredSkill={356,225},professionName="Fishing",prerequisitesAll={},prerequisitesAny={},children={},objectiveText={"Nat Pagle wants you to catch the following fish:","","Misty Reed Mahi Mahi from the Misty Reed Strand in the Swamp of Sorrows.","","A Sar'theris Striker from the Sar'theris Strand in Desolace.","","Feralas Ahi from the Verdantis River of Feralas.","","Savage Coast Blue Sailfin from the Savage Coast of Stranglethorn Vale.","","Return to Nat Pagle when you have reeled them all in!"},objectiveGroups={nil,nil,{{16967},{16970},{16968},{16969}}},requiredItems={},extraObjectives={},starters={{kind="npc",id=12919,name="Nat Pagle",dataSource="Database/TBC/tbcNpcDB.lua",points={{areaId=15,mapName="Dustwallow Marsh",x=58.76,y=60.17}}}},finishers={{kind="npc",id=12919,name="Nat Pagle",dataSource="Database/TBC/tbcNpcDB.lua",points={{areaId=15,mapName="Dustwallow Marsh",x=58.76,y=60.17}}}},objectives={{kind="item",id=16967,name="Feralas Ahi",dataSource="Database/TBC/tbcItemDB.lua",points={}},{kind="item",id=16970,name="Misty Reed Mahi Mahi",dataSource="Database/TBC/tbcItemDB.lua",points={}},{kind="item",id=16968,name="Sar'theris Striker",dataSource="Database/TBC/tbcItemDB.lua",points={}},{kind="item",id=16969,name="Savage Coast Blue Sailfin",dataSource="Database/TBC/tbcItemDB.lua",points={}}},exclusiveTo={},category="profession",geographic=true,kinds={"one_time","profession_gated","world"},recurrence="permanent",permanent=true,eventOnly=false,phaseStatus="current",sourceStatus="runtime",starter={kind="npc",id=12919,name="Nat Pagle",point={areaId=15,mapName="Dustwallow Marsh",x=58.76,y=60.17}},finisher={kind="npc",id=12919,name="Nat Pagle",point={areaId=15,mapName="Dustwallow Marsh",x=58.76,y=60.17}},objective={kind="item",id=16967,name="Feralas Ahi"},availabilityByPhase={"current","current"