  [7643] = {id=7643,name="Ancient Equine Spirit",questSort=-141,canonicalZone=1519,zoneName="Stormwind City",requiredLevel=60,questLevel=-1,requiredRaces=1029,requiredClasses=2,prerequisitesAll={},prerequisitesAny={7642},children={7645},nextQuest=7644,objectiveText={"Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food.","","Travel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it."},objectiveGroups={nil,nil,{{18775}}},sourceItem=18753,requiredItems={},extraObjectives={},starters={{kind="npc",id=928,name="Lord Grayson Shadowbreaker",dataSource="Database/TBC/tbcNpcDB.lua",points={{areaId=1519,mapName="Stormwind City",x=37.16,y=33.32}}}},finishers={{kind="npc",id=14566,name="Ancient Equine Spirit",dataSource="Database/TBC/tbcNpcDB.lua",points={}}},objectives={{kind="item",id=18775,name="Manna-Enriched Horse Feed",dataSource="Database/TBC/tbcItemDB.lua",points={}}},exclusiveTo={},category="dungeon",geographic=false,kinds={"dungeon","group_content","item_mechanic","one_time"},recurrence="permanent",permanent=true,eventOnly=false,phaseStatus="current",sourceStatus="runtime",starter={kind="npc",id=928,name="Lord Grayson Shadowbreaker",point={areaId=1519,mapName="Stormwind City",x=37.16,y=33.32}},finisher={kind="npc",id=14566,name="Ancient Equine Spirit"},objective={kind="item",id=18775,name="Manna-Enriched Horse Feed"},availabilityByPhase={"current","current","current","current","current"},unknownAvailability=false},
