  [7645] = {id=7645,name="Manna-Enriched Horse Feed",questSort=-141,canonicalZone=267,zoneName="Hillsbrad Foothills",requiredLevel=60,questLevel=-1,requiredRaces=1029,requiredClasses=2,prerequisitesAll={},prerequisitesAny={},children={},objectiveText={"Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills. The Argent Dawn is known as the sole purveyor of the biscuits.","","You also need to give her 50 gold to soothe her ruffled sensibilities."},objectiveGroups={nil,nil,{{13724}}},requiredItems={},extraObjectives={},starters={{kind="npc",id=2357,name="Merideth Carlson",dataSource="Database/TBC/tbcNpcDB.lua",points={{areaId=267,mapName="Hillsbrad Foothills",x=52.19,y=55.48}}}},finishers={{kind="npc",id=2357,name="Merideth Carlson",dataSource="Database/TBC/tbcNpcDB.lua",points={{areaId=267,mapName="Hillsbrad Foothills",x=52.19,y=55.48}}}},objectives={{kind="item",id=13724,name="Enriched Manna Biscuit",dataSource="Database/TBC/tbcItemDB.lua",points={}}},parentQuest=7643,exclusiveTo={},category="world",geographic=true,kinds={"one_time","world"},recurrence="permanent",permanent=true,eventOnly=false,phaseStatus="current",sourceStatus="runtime",starter={kind="npc",id=2357,name="Merideth Carlson",point={areaId=267,mapName="Hillsbrad Foothills",x=52.19,y=55.48}},finisher={kind="npc",id=2357,name="Merideth Carlson",point={areaId=267,mapName="Hillsbrad Foothills",x=52.19,y=55.48}},objective={kind="item",id=13724,name="Enriched Manna Biscuit"},availabilityByPhase={"current","current","current","current","current"},unknownAvailability=false},
