  [7647] = {id=7647,name="Judgment and Redemption",questSort=-141,canonicalZone=1519,zoneName="Stormwind City",requiredLevel=60,questLevel=-1,requiredRaces=1029,requiredClasses=2,prerequisitesAll={},prerequisitesAny={7646},children={},objectiveText={"Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger.","","Give the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger."},objectiveGroups={nil,nil,{{18799},{18792}}},sourceItem=18804,requiredItems={18749},extraObjectives={},starters={{kind="npc",id=928,name="Lord Grayson Shadowbreaker",dataSource="Database/TBC/tbcNpcDB.lua",points={{areaId=1519,mapName="Stormwind City",x=37.16,y=33.32}}}},finishers={{kind="npc",id=14568,name="Darkreaver's Fallen Charger",dataSource="Database/TBC/tbcNpcDB.lua",points={}}},objectives={{kind="item",id=18799,name="Charger's Redeemed Soul",dataSource="Database/TBC/tbcItemDB.lua",points={}},{kind="item",id=18792,name="Blessed Arcanite Barding",dataSource="Database/TBC/tbcItemDB.lua",points={}}},exclusiveTo={},category="dungeon",geographic=false,kinds={"dungeon","group_content","item_mechanic","one_time"},recurrence="permanent",permanent=true,eventOnly=false,phaseStatus="current",sourceStatus="runtime",starter={kind="npc",id=928,name="Lord Grayson Shadowbreaker",point={areaId=1519,mapName="Stormwind City",x=37.16,y=33.32}},finisher={kind="npc",id=14568,name="Darkreaver's Fallen Charger"},objective={kind="item",id=18799,name="Charger's Redeemed Soul"},availabilityByPhase={"current","current","current","current","current"},unknownAvailability=false},
